#include <string>
#include <vector>
#include <set>
#include <algorithm>
#include <climits>

class Solution {
public:
    int maxDifference(std::string s, int k) {
        std::set<char> char_set(s.begin(), s.end());
        std::vector<char> chars(char_set.begin(), char_set.end());
        int ans = INT_MIN;

        for (char a : chars) {
            for (char b : chars) {
                if (a == b) continue;

                std::vector<std::vector<int>> min_diff(2, std::vector<int>(2, INT_MAX / 2));
                std::vector<int> prefix_a = {0};
                std::vector<int> prefix_b = {0};
                int l = 0;

                for (int r = 0; r < (int)s.length(); ++r) {
                    prefix_a.push_back(prefix_a.back() + (s[r] == a ? 1 : 0));
                    prefix_b.push_back(prefix_b.back() + (s[r] == b ? 1 : 0));

                    while (r - l + 1 >= k &&
                           prefix_a[l] < prefix_a.back() &&
                           prefix_b[l] < prefix_b.back()) {
                        int pa = prefix_a[l] % 2;
                        int pb = prefix_b[l] % 2;
                        min_diff[pa][pb] = std::min(min_diff[pa][pb], prefix_a[l] - prefix_b[l]);
                        l++;
                    }

                    int req_pa = 1 - (prefix_a.back() % 2);
                    int req_pb = prefix_b.back() % 2;
                    int best_sub = min_diff[req_pa][req_pb];
                    if (best_sub < INT_MAX / 4) {
                        int cand = (prefix_a.back() - prefix_b.back()) - best_sub;
                        ans = std::max(ans, cand);
                    }
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxDifference(String s, int k) {
        Set<Character> charSet = new TreeSet<>();
        for (char c : s.toCharArray()) charSet.add(c);
        List<Character> chars = new ArrayList<>(charSet);

        int ans = Integer.MIN_VALUE;
        int INF = Integer.MAX_VALUE / 2;

        for (char a : chars) {
            for (char b : chars) {
                if (a == b) continue;

                int[][] minDiff = new int[2][2];
                for (int i = 0; i < 2; i++) Arrays.fill(minDiff[i], INF);

                int[] prefixA = new int[s.length() + 1];
                int[] prefixB = new int[s.length() + 1];
                int l = 0;

                for (int r = 0; r < s.length(); r++) {
                    prefixA[r + 1] = prefixA[r] + (s.charAt(r) == a ? 1 : 0);
                    prefixB[r + 1] = prefixB[r] + (s.charAt(r) == b ? 1 : 0);

                    while (r - l + 1 >= k &&
                           prefixA[l] < prefixA[r + 1] &&
                           prefixB[l] < prefixB[r + 1]) {
                        int pa = prefixA[l] % 2;
                        int pb = prefixB[l] % 2;
                        minDiff[pa][pb] = Math.min(minDiff[pa][pb], prefixA[l] - prefixB[l]);
                        l++;
                    }

                    int reqPa = 1 - (prefixA[r + 1] % 2);
                    int reqPb = prefixB[r + 1] % 2;
                    int bestSub = minDiff[reqPa][reqPb];
                    if (bestSub < INF / 2) {
                        int cand = (prefixA[r + 1] - prefixB[r + 1]) - bestSub;
                        ans = Math.max(ans, cand);
                    }
                }
            }
        }
        return ans;
    }
}

var maxDifference = function(s, k) {
    const charSet = new Set(s);
    const chars = Array.from(charSet).sort();
    let ans = -Infinity;
    const INF = 1e9;

    for (const a of chars) {
        for (const b of chars) {
            if (a === b) continue;

            const minDiff = [[INF, INF], [INF, INF]];
            const prefixA = [0];
            const prefixB = [0];
            let l = 0;

            for (let r = 0; r < s.length; r++) {
                prefixA.push(prefixA[prefixA.length - 1] + (s[r] === a ? 1 : 0));
                prefixB.push(prefixB[prefixB.length - 1] + (s[r] === b ? 1 : 0));

                while (r - l + 1 >= k &&
                       prefixA[l] < prefixA[prefixA.length - 1] &&
                       prefixB[l] < prefixB[prefixB.length - 1]) {
                    const pa = prefixA[l] % 2;
                    const pb = prefixB[l] % 2;
                    const diff = prefixA[l] - prefixB[l];
                    if (diff < minDiff[pa][pb]) minDiff[pa][pb] = diff;
                    l++;
                }

                const reqPa = 1 - (prefixA[prefixA.length - 1] % 2);
                const reqPb = prefixB[prefixB.length - 1] % 2;
                const bestSub = minDiff[reqPa][reqPb];
                if (bestSub < INF / 2) {
                    const cand = (prefixA[prefixA.length - 1] - prefixB[prefixA.length - 1 < prefixB.length ? prefixA.length - 1 : prefixB.length - 1]) - bestSub;
                    const actualDiff = (prefixA[prefixA.length - 1] - prefixB[prefixB.length - 1]) - bestSub;
                    if (actualDiff > ans) ans = actualDiff;
                }
            }
        }
    }
    return ans;
};
